const s = wb.getWorksheet('Sheet1'), p = wb.getWorksheet('Sheet2');
log(s.getRange('A1:F14'));
const diffs=[];
for (let r=1;r<=14;r++) for (const c of 'ABCDEF') {
  const x=s.getRange(c+r).getCell(), y=p.getRange(c+r).getCell();
  if (x.getValue()!==y.getValue() || x.getText()!==y.getText()) diffs.push([c+r,x.getValue(),y.getValue(),x.getText(),y.getText()]);
}
log('diffs', JSON.stringify(diffs));
log(JSON.stringify(['D11','E11','C11','F3','F6','F8','F9'].map(a=>[a,s.getRange(a).getCell().getText(),p.getRange(a).getCell().getText()])));
log(s.getRegions('alignment')); log(s.getRegions('font')); log(s.getRegions('numberFormat')); log(p.getRegions('numberFormat'));

